import express from 'express';

class AppError extends Error {
  constructor(status, message, code) {
    super(message);
    this.status = status;
    this.code = code;
  }
}

const app = express();
const users = new Map([['1', { id: '1', name: 'Rafi' }]]);

// Express 5: a throw inside an async handler is forwarded to the error handler
app.get('/users/:id', async (req, res) => {
  const user = users.get(req.params.id); // imagine: await User.findById(req.params.id)
  if (!user) throw new AppError(404, 'User not found', 'NOT_FOUND');
  res.json(user);
});

// Callback-style code runs outside the promise chain: pass the error on manually
app.get('/legacy', (req, res, next) => {
  setTimeout(() => next(new AppError(503, 'Legacy service down', 'UNAVAILABLE')), 10);
});

app.use((req, res) => res.status(404).json({ error: { message: 'Route not found', code: 'NOT_FOUND' } }));

app.use((err, req, res, next) => {
  if (res.headersSent) return next(err); // let Express close the connection
  const status = err.status ?? 500;
  if (status >= 500) console.error(err); // log unexpected errors with their stack
  const hide = status >= 500 && process.env.NODE_ENV === 'production';
  res.status(status).json({
    error: { message: hide ? 'Internal server error' : err.message, code: err.code ?? 'INTERNAL' },
  });
});

app.listen(3000);

import express from 'express';
import { z } from 'zod';

const app = express();
app.use(express.json({ limit: '10kb' }));

const tasks = new Map(); // id -> task (swap for a Mongoose model later)
let nextId = 1;

const title = z.string().trim().min(1).max(100);
const createSchema = z.object({ title }).strict();
const updateSchema = z.object({ title, done: z.boolean() }).partial().strict();
const listSchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(50).default(10),
});

const notFound = (res) => res.status(404).json({ error: { code: 'NOT_FOUND', message: 'Task not found' } });

function validate(schema, data, res) {
  const result = schema.safeParse(data);
  if (result.success) return result.data;
  res.status(400).json({ error: { code: 'VALIDATION_ERROR', details: result.error.issues } });
  return null;
}

app.get('/api/tasks', (req, res) => {
  const q = validate(listSchema, req.query, res);
  if (!q) return;
  const all = [...tasks.values()];
  const items = all.slice((q.page - 1) * q.limit, q.page * q.limit);
  res.json({ items, page: q.page, limit: q.limit, total: all.length });
});

app.get('/api/tasks/:id', (req, res) => {
  const task = tasks.get(Number(req.params.id));
  if (!task) return notFound(res);
  res.json(task);
});

app.post('/api/tasks', (req, res) => {
  const body = validate(createSchema, req.body, res);
  if (!body) return;
  const task = { id: nextId++, title: body.title, done: false };
  tasks.set(task.id, task);
  res.status(201).location(`/api/tasks/${task.id}`).json(task);
});

app.patch('/api/tasks/:id', (req, res) => {
  const task = tasks.get(Number(req.params.id));
  if (!task) return notFound(res);
  const changes = validate(updateSchema, req.body, res);
  if (!changes) return;
  Object.assign(task, changes);
  res.json(task);
});

app.delete('/api/tasks/:id', (req, res) => {
  if (!tasks.delete(Number(req.params.id))) return notFound(res);
  res.status(204).end();
});

