import express from 'express';
import cookieParser from 'cookie-parser';
import jwt from 'jsonwebtoken';
import bcrypt from 'bcryptjs';

const app = express();
app.use(express.json());
app.use(cookieParser());

const SECRET = process.env.JWT_SECRET; // long random value from the environment, never committed
const users = [{ id: '42', email: 'mitu@example.com', passwordHash: bcrypt.hashSync('correct-horse', 12) }];

app.post('/api/auth/login', async (req, res) => {
  const user = users.find((u) => u.email === req.body?.email);
  const ok = user && (await bcrypt.compare(String(req.body.password), user.passwordHash));
  if (!ok) return res.status(401).json({ error: 'Invalid email or password' });

  const token = jwt.sign({ sub: user.id }, SECRET, { algorithm: 'HS256', expiresIn: '15m' });
  res.cookie('token', token, { httpOnly: true, secure: true, sameSite: 'lax', maxAge: 15 * 60 * 1000 });
  res.json({ user: { id: user.id, email: user.email } });
});

function requireAuth(req, res, next) {
  const header = req.get('authorization');
  const token = req.cookies.token ?? (header?.startsWith('Bearer ') ? header.slice(7) : null);
  if (!token) return res.status(401).json({ error: 'Not logged in' });
  try {
    const payload = jwt.verify(token, SECRET, { algorithms: ['HS256'] }); // signature + exp
    req.user = { id: payload.sub };
    next();
  } catch {
    res.status(401).json({ error: 'Invalid or expired token' });
  }
}

app.get('/api/me', requireAuth, (req, res) => res.json({ user: req.user }));
app.post('/api/auth/logout', (req, res) => res.clearCookie('token', { httpOnly: true, secure: true, sameSite: 'lax' }).json({ ok: true }));

app.listen(3000);

import { createReadStream, createWriteStream } from 'node:fs';
import { stat } from 'node:fs/promises';
import { pipeline } from 'node:stream/promises';
import { createGzip } from 'node:zlib';
import express from 'express';

// 1. Compress a huge file with constant memory: read -> gzip -> write
await pipeline(
  createReadStream('access.log'), // 64 KiB chunks
  createGzip(), // transform stream
  createWriteStream('access.log.gz'),
); // rejects, and destroys every stream, if any step fails

// 2. Send a big file to an HTTP client without loading it into memory
const app = express();
app.get('/download', async (req, res) => {
  const file = 'access.log.gz';
  const { size } = await stat(file); // missing file -> rejection -> Express 5 error handler
  res.attachment(file).set('Content-Length', size);
  // Backpressure: a slow client pauses the disk reads. If the copy fails midway,
  // pipeline destroys res too, so the client sees an aborted download, not a corrupt 200.
  await pipeline(createReadStream(file), res);
});
app.listen(3000);

// server.mjs — cluster for throughput + a worker thread for CPU-heavy work
import cluster from 'node:cluster';
import { availableParallelism } from 'node:os';
import { Worker } from 'node:worker_threads';
import express from 'express';

if (cluster.isPrimary) {
  for (let i = 0; i < availableParallelism(); i++) cluster.fork();
  cluster.on('exit', (worker) => {
    console.log(`worker ${worker.process.pid} died, starting a new one`);
    cluster.fork();
  });
} else {
  const app = express();
  app.get('/health', (req, res) => res.json({ ok: true, pid: process.pid }));

  // CPU-heavy: run it on a worker thread so this process keeps serving /health
  // (production: reuse a pool such as Piscina instead of one thread per request)
  app.get('/fib/:n', (req, res, next) => {
    const worker = new Worker(new URL('./fib-worker.mjs', import.meta.url), {
      workerData: Number(req.params.n),
    });
    worker.once('message', (result) => res.json({ result }));
    worker.once('error', next);
  });

  app.listen(3000);
}

