class EventEmitter {
  constructor() {
    this.events = new Map(); // event name -> array of listeners
  }

  on(event, listener) {
    if (!this.events.has(event)) this.events.set(event, []);
    this.events.get(event).push(listener);
    return this;
  }

  off(event, listener) {
    const list = this.events.get(event);
    if (!list) return this;
    const i = list.findIndex((l) => l === listener || l.original === listener);
    if (i !== -1) list.splice(i, 1);
    if (list.length === 0) this.events.delete(event);
    return this;
  }

  once(event, listener) {
    const wrapper = (...args) => {
      this.off(event, wrapper); // remove first, then call
      listener.apply(this, args);
    };
    wrapper.original = listener;
    return this.on(event, wrapper);
  }

  emit(event, ...args) {
    const list = this.events.get(event);
    if (!list) return false;
    for (const listener of [...list]) listener.apply(this, args); // snapshot copy
    return true;
  }
}

class EventEmitter:
    def __init__(self):
        self.events = {}  # event name -> list of listeners

    def on(self, event, listener):
        self.events.setdefault(event, []).append(listener)
        return self

    def off(self, event, listener):
        lst = self.events.get(event)
        if lst is None:
            return self
        for i, l in enumerate(lst):
            if l == listener or getattr(l, "original", None) == listener:
                del lst[i]
                break
        if not lst:
            del self.events[event]
        return self

    def once(self, event, listener):
        def wrapper(*args):
            self.off(event, wrapper)  # remove first, then call
            listener(*args)
        wrapper.original = listener
        return self.on(event, wrapper)

    def emit(self, event, *args):
        lst = self.events.get(event)
        if lst is None:
            return False
        for listener in list(lst):  # snapshot copy
            listener(*args)
        return True

import java.util.*;
import java.util.function.Consumer;

class EventEmitter {
    private final Map<String, List<Consumer<Object[]>>> events = new HashMap<>();

    // remembers the original listener so off(event, original) can find it
    private record Once(EventEmitter owner, String event, Consumer<Object[]> original) implements Consumer<Object[]> {
        public void accept(Object[] args) {
            owner.off(event, this); // remove first, then call
            original.accept(args);
        }
    }

    public EventEmitter on(String event, Consumer<Object[]> listener) {
        events.computeIfAbsent(event, k -> new ArrayList<>()).add(listener);
        return this;
    }

    public EventEmitter off(String event, Consumer<Object[]> listener) {
        List<Consumer<Object[]>> list = events.get(event);
        if (list == null) return this;
        for (int i = 0; i < list.size(); i++) {
            Consumer<Object[]> l = list.get(i);
            if (l == listener || (l instanceof Once w && w.original() == listener)) { list.remove(i); break; }
        }
        if (list.isEmpty()) events.remove(event);
        return this;
    }

    public EventEmitter once(String event, Consumer<Object[]> listener) { return on(event, new Once(this, event, listener)); }

    public boolean emit(String event, Object... args) {
        List<Consumer<Object[]>> list = events.get(event);
        if (list == null) return false;
        for (Consumer<Object[]> l : new ArrayList<>(list)) l.accept(args); // snapshot copy
        return true;
    }
}

